/// <summary>
/// Bug 290034: CB201- For volumetric rebate Process>Rebate transaction, Source transaction is not looking at the Rebate management number of Tier Line type Value
/// </summary>
[ExtensionOf(classStr(TAMRebateCalculateDateTransaction))]
final class METTAMRebateCalculateDateTransaction_Extension
{
}

Method.Source:
/// <summary>
/// When there is no TAMRebateLine, no rebate transactions are created by default (see TAMRebateCalculateDateTransaction\calculateRebate)
/// Therefore for the volumetric rebate value line, we are retrieving the TAMRebateLine from the corresponding rate line
/// This will ensure rebate transactions are inserted and trigger the custom logic to recalc the rebate amount based on Tier rate transactions
/// </summary>
/// <param name = "_rebateDate"><c>TAMRebateDate</c></param>
/// <returns><c>TAMRebateLine</c></returns>
protected TAMRebateLine selectRebateLine(TAMRebateDate _rebateDate)
{
    TAMRebateLine rebateLine = next selectRebateLine(_rebateDate);

    // For volumetric rebate value line there is no TAMRebateLine configured with qty/value
    if (!rebateLine
    &&  rebateDeal.METVolumetricTierDeal
    &&  rebateTable.METTierLineType == METTierLineType::Value)
    {
        // Retrieve the volumetric rebate rate line 
        TAMRebateTable rebateTableRate;
        select firstonly RebateId from rebateTableRate
                                 where rebateTableRate.RebateDeal == rebateDeal.RecId
                                    && rebateTableRate.METTierLineType == METTierLineType::Rate;

        // Retrieve the TAMRebateLine from the volumetric rebate rate line instead
        select rebateLine order by RebateFrom asc
         where rebateLine.RebateId == rebateTableRate.RebateId
            && rebateLine.RefLineNum == _rebateDate.LineNum;
    }

    return rebateLine;
}
